import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // root container
  const root = new Group();

  // plane geometry (aspect 512:320 = 1.6:1)
  const geometry = new PlaneGeometry(1.6, 1);
  const material = new MeshBasicNodeMaterial();
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // apply cinematic primitives if any
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const inst = ctx.primitives[prim.name](root, prim.params);
      primitiveInstances.push(inst);
    }
  }

  // placeholder for event handlers
  root.userData.handlers = {};

  // cleanup routine
  root.userData.cleanup = () => {
    // dispose material and geometry
    material.dispose();
    geometry.dispose();
    if (material.map) material.map.dispose();

    // kill any GSAP animations tied to this mesh
    gsap.killTweensOf(mesh);

    // cleanup primitives
    for (const inst of primitiveInstances) {
      if (inst.cleanup) inst.cleanup();
    }
  };

  return root;
}
